(async()=>{const status=document.getElementById('daily-status'),select=document.getElementById('daily-list'),frame=document.getElementById('daily-frame');let id,base;
 const request=async query=>{const response=await fetch(base+'/rest/v1/daily-briefs?'+query,{headers:Auth.authHeaders()});if(!response.ok)throw Error('日报读取失败，请检查登录或功能初始化状态');return response;};
 async function open(){id=select.value;if(!id)return;status.textContent='正在读取日报…';try{frame.srcdoc=await (await request('id='+encodeURIComponent(id)+'&format=html')).text();status.textContent='已读取归档日报；后续补录以修订版为准。';for(const kind of ['html','png'])document.getElementById('daily-'+kind).disabled=false;}catch(e){status.textContent=e.message;}}
 async function download(kind){try{const response=await request('id='+encodeURIComponent(id)+'&format='+kind),url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='艾维经营日报-'+id+'.'+kind;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){status.textContent=e.message;}}
 try{Auth.init();window.opener=null;if(!Auth.canReadOperationsReports())throw Error('请先在主系统登录，再打开日报。');base=await Store._ensureClient();const followDate=document.getElementById('followup-date'),followState=document.getElementById('followup-state');
followDate.value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date());
async function refreshFollowup(){try{const d=await(await request('status=1&date='+encodeURIComponent(followDate.value))).json();const labels={pending:'等待发送',sending:'投递处理中',accepted:'接口已接受',retry:'等待有限重试',uncertain:'投递不确定，禁止自动重发',failed:'发送失败'};followState.textContent=[d.date+'｜'+d.memberReceipt,d.reminder,d.delivery.length?'':'暂无发送账本，请检查日报生成和定时任务。',...d.delivery.map(e=>(e.kind==='initial'?'首次日报':'更正'+e.sequence)+'：'+(labels[e.state]||e.state)+'；尝试'+e.attempts+'次'+(e.last_code?'；结果码 '+e.last_code:'')),...d.incidents.filter(e=>e.state==='open').map(e=>'待处理：'+e.code+'；'+(e.detail.cause||e.detail.reason||'')+'；负责人 '+(e.detail.owner||'待指定')),d.followup?.detail?.reviewState||'',d.followup?.detail?.inventoryClosingMismatch?'库存模块闭馆时间与17:30不一致，请核对统一设置。':''].filter(Boolean).join(String.fromCharCode(10));}catch{followState.textContent='当前账号不可读取发送状态，或闭环功能尚未初始化。';}}
document.getElementById('followup-refresh').onclick=refreshFollowup;await refreshFollowup();
const data=await (await request('limit=50')).json();select.replaceChildren();for(const r of data.reports){const o=document.createElement('option');o.value=r.id;o.textContent=r.business_date+' · v'+r.revision;select.appendChild(o);}if(!data.reports.length){status.textContent='尚无已归档日报。';return;}select.onchange=open;for(const kind of ['html','png'])document.getElementById('daily-'+kind).onclick=()=>download(kind);await open();}catch(e){status.textContent=e.message;select.replaceChildren();}
})();
